import numpy as np


class AdaptiveRestartLocalDE:
    """Feasibility-rule jDE (current-to-pbest/1) with IPOP population growth on stalls,
    alternating random / incumbent-seeded / archive-seeded epochs. After every DE epoch
    the incumbent gets a 1/5-rule Gaussian/Cauchy search and a step-halving coordinate
    pattern search, so the search keeps exploiting promising basins down to fine scales
    and restarts explore new basins when a DE epoch stalls."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vt = list(func.variable_types)
        ci = np.asarray(func.continuous_indices, dtype=int)
        ii = np.asarray(func.integer_indices, dtype=int)

        nv = np.ones(d, dtype=int)
        for i in ii:
            nv[i] = int(func.n_values[i])
        span = ub - lb

        st = {"n": 0, "bf": np.inf, "bx": None, "bt": None, "last_imp": 0}
        archive = []
        SIG_FLOOR = 1e-6
        SIG_MAX = 0.5

        def can():
            return st["n"] < self.budget

        def repair(x):
            x = np.clip(np.asarray(x, dtype=float), lb, ub)
            if ii.size:
                x[ii] = np.clip(np.rint(x[ii]), 0, nv[ii] - 1)
            return x

        def key(t):
            return (t[2], t[1])

        def evaluate(x):
            x = repair(x)
            f, g = func(x)
            st["n"] += 1
            g = np.asarray(g, dtype=float).ravel()
            g = np.where(np.isfinite(g), g, 1e6)
            v = float(np.sum(np.maximum(g, 0.0)))
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
                v += 1.0
            t = (x, f, v)
            if v == 0.0 and f < st["bf"]:
                st["bf"] = f
                st["bx"] = x.copy()
                st["last_imp"] = st["n"]
            if st["bt"] is None or key(t) < key(st["bt"]):
                st["bt"] = t
            return t

        def random_point():
            x = np.empty(d)
            if ci.size:
                x[ci] = np.random.uniform(lb[ci], ub[ci])
            if ii.size:
                x[ii] = np.random.randint(0, nv[ii])
            return x

        def mutate_int(val, k):
            if nv[k] <= 1:
                return 0.0
            if vt[k] == "ordinal":
                step = 1 if np.random.rand() < 0.5 else -1
                new = val + step
                if new < 0 or new > nv[k] - 1:
                    new = val - step
                return float(np.clip(new, 0, nv[k] - 1))
            choices = [c for c in range(nv[k]) if c != int(round(val))]
            return float(np.random.choice(choices))

        def heavy_step(n):
            if np.random.rand() < 0.3:
                return np.clip(np.tan(np.pi * (np.random.rand(n) - 0.5)), -20, 20)
            return np.random.randn(n)

        def perturb(x, scale):
            y = x.copy()
            if ci.size:
                m = np.random.rand(ci.size) < 0.5
                m[np.random.randint(ci.size)] = True
                y[ci] = y[ci] + np.where(m, scale * span[ci] * np.random.randn(ci.size), 0.0)
            if ii.size:
                p = min(1.0, max(1.0 / ii.size, scale * 2))
                flip = np.random.rand(ii.size) < p
                for k in ii[flip]:
                    y[k] = mutate_int(y[k], k)
            return repair(y)

        def local_search(start, sig, ls_budget):
            """1/5-rule search with heavy-tailed / Gaussian steps and sigma floor."""
            cur = start
            fails = 0
            for _ in range(ls_budget):
                if not can():
                    break
                y = cur[0].copy()
                if ci.size:
                    m = np.random.rand(ci.size) < 0.5
                    m[np.random.randint(ci.size)] = True
                    step = sig * span[ci] * heavy_step(ci.size)
                    y[ci] = y[ci] + np.where(m, step, 0.0)
                if ii.size:
                    flip = np.random.rand(ii.size) < (1.0 / ii.size)
                    for k in ii[flip]:
                        y[k] = mutate_int(y[k], k)
                cand = evaluate(y)
                if key(cand) < key(cur):
                    cur = cand
                    sig = min(sig * 1.5, SIG_MAX)
                    fails = 0
                else:
                    sig = max(sig * 1.5 ** (-0.25), SIG_FLOOR)
                    fails += 1
                    if fails >= 8 and sig <= 2 * SIG_FLOOR:
                        sig = 10.0 ** np.random.uniform(-3, -0.5)
                        fails = 0
            return cur, sig

        def pattern_search(center, step0):
            """Coordinate pattern search with step halving down to a fine scale."""
            cur = center
            step = step0
            while can() and step > 1e-6:
                improved = False
                coords = list(ci) + list(ii)
                np.random.shuffle(coords)
                for k in coords:
                    if not can():
                        break
                    for s in ((1.0, -1.0) if k in ci else (1, -1)):
                        if not can():
                            break
                        y = cur[0].copy()
                        if k in ci:
                            y[k] = y[k] + s * step * span[k]
                        else:
                            new = y[k] + s
                            if new < 0 or new > nv[k] - 1:
                                continue
                            y[k] = new
                        cand = evaluate(y)
                        if key(cand) < key(cur):
                            cur = cand
                            improved = True
                            break
                if not improved:
                    step *= 0.5
            return cur

        def refine_incumbent(sig):
            if not can() or st["bt"] is None or st["bt"][2] != 0.0:
                return sig
            st["bt"] = pattern_search(st["bt"], 10.0 ** np.random.uniform(-3, -1))
            if can() and (ci.size or ii.size):
                if sig <= SIG_FLOOR:
                    sig = 10.0 ** np.random.uniform(-2, -0.5)
                _, sig = local_search(st["bt"], sig, max(4, 2 * d))
            if st["bt"][2] == 0.0 and st["bt"][1] < st["bf"]:
                st["bf"] = st["bt"][1]
                st["bx"] = st["bt"][0].copy()
                st["last_imp"] = st["n"]
            return sig

        N0 = max(8, min(40, 3 * d + 4))
        if self.budget < 10 * N0:
            N0 = max(4, self.budget // 10)
        stall_limit = 10 + d
        grow = 0
        epoch = 0
        sig_global = 0.1
        pm_int = min(0.5, max(1.0 / max(1, ii.size), 0.05))

        while can():
            phase = epoch % 3  # 0: incumbent-seeded, 1: archive-seeded, 2: random restart
            if phase == 2:
                grow = min(grow + 1, 3)  # IPOP growth across random restarts
            N = min(N0 * (2 ** grow), 160)

            pop = []
            if phase in (0, 1) and st["bt"] is not None:
                if phase == 0 or not archive:
                    center = st["bt"]
                else:
                    idx = min(int(np.random.exponential(2.0)), len(archive) - 1)
                    center = archive[idx]
                pop.append(center)
                for _ in range(int(0.6 * N)):
                    if not can():
                        break
                    scale = 10.0 ** np.random.uniform(-3, np.log10(0.3))
                    pop.append(evaluate(perturb(center[0], scale)))
            while len(pop) < N and can():
                pop.append(evaluate(random_point()))
            if len(pop) < 4:
                break
            N = len(pop)

            Fa = np.full(N, 0.5)
            CRa = np.full(N, 0.9)
            n_pbest = max(2, int(0.2 * N))
            best_key = min(key(p) for p in pop)
            stall = 0
            sig = 0.1

            while can():
                order = sorted(range(N), key=lambda j: key(pop[j]))
                pb_pool = order[:n_pbest]

                for i in range(N):
                    if not can():
                        break
                    xi = pop[i][0]
                    Ft = np.random.uniform(0.1, 1.0) if np.random.rand() < 0.1 else Fa[i]
                    CRt = np.random.rand() if np.random.rand() < 0.1 else CRa[i]

                    cands = [j for j in range(N) if j != i]
                    r = np.random.choice(cands, 2, replace=False)
                    xr1, xr2 = pop[r[0]][0], pop[r[1]][0]
                    pbest = pop[pb_pool[np.random.randint(len(pb_pool))]][0]
                    trial = xi.copy()

                    if ci.size:
                        if np.random.rand() < 0.6:
                            mutant = xi + Ft * (pbest - xi) + Ft * (xr1 - xr2)
                        else:
                            xr3 = pop[np.random.randint(N)][0]
                            mutant = xr1 + Ft * (xr2 - xr3)
                        mask = np.random.rand(ci.size) < CRt
                        mask[np.random.randint(ci.size)] = True
                        trial[ci] = np.where(mask, mutant[ci], xi[ci])

                    if ii.size:
                        donor = pbest if np.random.rand() < 0.5 else xr1
                        mask = np.random.rand(ii.size) < CRt
                        mask[np.random.randint(ii.size)] = True
                        trial[ii] = np.where(mask, donor[ii], xi[ii])
                        mut = np.random.rand(ii.size) < pm_int
                        for k in ii[mut]:
                            trial[k] = mutate_int(trial[k], k)

                    cand = evaluate(trial)
                    if key(cand) <= key(pop[i]):
                        pop[i] = cand
                        Fa[i] = Ft
                        CRa[i] = CRt

                if can() and (ci.size or ii.size):
                    cur = min(pop, key=key)
                    cur, sig = local_search(cur, sig, max(4, d))
                    worst = max(range(N), key=lambda j: key(pop[j]))
                    if key(cur) < key(pop[worst]):
                        pop[worst] = cur
                        Fa[worst] = 0.5
                        CRa[worst] = 0.9

                cur_best = min(key(p) for p in pop)
                if cur_best < best_key:
                    best_key = cur_best
                    stall = 0
                else:
                    stall += 1
                if stall >= stall_limit:
                    break
                if ci.size:
                    cstd = np.std(np.array([p[0][ci] for p in pop]), axis=0).max()
                else:
                    cstd = 1.0
                if cstd < 1e-7 and stall >= 3:
                    break

            ebest = min(pop, key=key)
            if ebest[2] == 0.0 and np.isfinite(ebest[1]):
                archive.append(ebest)
                archive.sort(key=key)
                if len(archive) > 10:
                    archive.pop()

            # Exploit the incumbent after each epoch (pattern search + 1/5 rule)
            sig_global = refine_incumbent(sig_global)
            epoch += 1

        return st["bf"], st["bx"]
